-- Hand-written (not generated by `prisma migrate dev`, which would have
-- proposed dropping `checkout_addons` and losing the 3 existing rows plus
-- their order_addons linkage). This preserves data: addon rows keep their
-- ids (so historical order_addons references stay valid), and a new join
-- table captures the page <-> addon relationship + per-page display order
-- that used to live directly on checkout_addons.

-- Turn the page-scoped checkout_addons table into the global addons pool.
ALTER TABLE "checkout_addons" RENAME TO "addons";
ALTER TABLE "addons" RENAME CONSTRAINT "checkout_addons_pkey" TO "addons_pkey";

-- Join table: which addons are on which checkout page, and in what order.
CREATE TABLE "checkout_page_addons" (
    "id" UUID NOT NULL,
    "checkout_page_id" UUID NOT NULL,
    "addon_id" UUID NOT NULL,
    "sort_order" INTEGER NOT NULL DEFAULT 0,

    CONSTRAINT "checkout_page_addons_pkey" PRIMARY KEY ("id")
);

-- Backfill the join table from the addons' current page/order columns
-- before those columns are dropped.
INSERT INTO "checkout_page_addons" ("id", "checkout_page_id", "addon_id", "sort_order")
SELECT gen_random_uuid(), "checkout_page_id", "id", "sort_order" FROM "addons";

-- addons is global now — drop its old page-scoping columns.
ALTER TABLE "addons" DROP CONSTRAINT "checkout_addons_checkout_page_id_fkey";
ALTER TABLE "addons" DROP COLUMN "checkout_page_id";
ALTER TABLE "addons" DROP COLUMN "sort_order";

-- Foreign keys + uniqueness for the join table.
ALTER TABLE "checkout_page_addons" ADD CONSTRAINT "checkout_page_addons_checkout_page_id_fkey" FOREIGN KEY ("checkout_page_id") REFERENCES "checkout_pages"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "checkout_page_addons" ADD CONSTRAINT "checkout_page_addons_addon_id_fkey" FOREIGN KEY ("addon_id") REFERENCES "addons"("id") ON DELETE CASCADE ON UPDATE CASCADE;
CREATE UNIQUE INDEX "checkout_page_addons_checkout_page_id_addon_id_key" ON "checkout_page_addons"("checkout_page_id", "addon_id");

-- order_addons.checkout_addon_id -> addon_id (same values, same FK target,
-- since checkout_addons was renamed to addons in place above).
ALTER TABLE "order_addons" RENAME COLUMN "checkout_addon_id" TO "addon_id";
ALTER TABLE "order_addons" RENAME CONSTRAINT "order_addons_checkout_addon_id_fkey" TO "order_addons_addon_id_fkey";
